// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.ui.screensimport androidx.compose.foundation.backgroundimport androidx.compose.foundation.clickableimport androidx.compose.foundation.layout.Arrangementimport androidx.compose.foundation.layout.Columnimport androidx.compose.foundation.layout.Rowimport androidx.compose.foundation.layout.Spacerimport androidx.compose.foundation.layout.fillMaxSizeimport androidx.compose.foundation.layout.fillMaxWidthimport androidx.compose.foundation.layout.paddingimport androidx.compose.foundation.layout.sizeimport androidx.compose.foundation.lazy.LazyColumnimport androidx.compose.foundation.lazy.itemsimport androidx.compose.foundation.shape.RoundedCornerShapeimport androidx.compose.material.icons.Iconsimport androidx.compose.material.icons.automirrored.filled.KeyboardArrowRightimport androidx.compose.material3.Iconimport androidx.compose.material3.MaterialThemeimport androidx.compose.material3.Textimport androidx.compose.runtime.Composableimport androidx.compose.runtime.collectAsStateimport androidx.compose.runtime.getValueimport androidx.compose.ui.Alignmentimport androidx.compose.ui.Modifierimport androidx.compose.ui.graphics.vector.ImageVectorimport androidx.compose.ui.text.font.FontWeightimport androidx.compose.ui.unit.dpimport com.roshan.persona.ui.components.GlassPanelimport com.roshan.persona.ui.components.StatChipimport com.roshan.persona.ui.state.UiStateProvider/** * Settings entry — one row in the settings list. */data class SettingsEntry(    val id: String,    val title: String,    val subtitle: String,    val icon: ImageVector? = null,)/** * Settings group — a titled section of entries. */data class SettingsGroup(    val title: String,    val entries: List<SettingsEntry>,)/** * Settings screen (master). * * @param groups list of setting groups (passed by host — host knows what's available) * @param onEntryClick callback when an entry is tapped * @param stateProvider for live status (LLM loaded, voice state, etc.) */@Composablefun SettingsScreen(    groups: List<SettingsGroup>,    onEntryClick: (SettingsEntry) -> Unit,    stateProvider: UiStateProvider,    modifier: Modifier = Modifier,) {    val localLlmLoaded by stateProvider.localLlmLoaded.collectAsState()    val localLlmName by stateProvider.localLlmModelName.collectAsState()    val cloudProvider by stateProvider.cloudProviderName.collectAsState()    val monthlyCost by stateProvider.monthlyCostUsd.collectAsState()    val monthlyBudget by stateProvider.monthlyBudgetUsd.collectAsState()    val sttEngine by stateProvider.sttEngineName.collectAsState()    val ttsEngine by stateProvider.ttsEngineName.collectAsState()    val wakeWordActive by stateProvider.wakeWordActive.collectAsState()    val speakerCount by stateProvider.speakerCount.collectAsState()    LazyColumn(        modifier = modifier            .fillMaxSize()            .background(MaterialTheme.colorScheme.background),        contentPadding = androidx.compose.foundation.layout.PaddingValues(16.dp),        verticalArrangement = Arrangement.spacedBy(16.dp),    ) {        item {            Text(                text = "Settings",                style = MaterialTheme.typography.headlineLarge,                fontWeight = FontWeight.Bold,                color = MaterialTheme.colorScheme.onBackground,            )        }        // Live status card        item {            GlassPanel(title = "System Status") {                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {                    Row(                        modifier = Modifier.fillMaxWidth(),                        horizontalArrangement = Arrangement.spacedBy(8.dp),                    ) {                        StatChip(                            label = "Local LLM",                            value = if (localLlmLoaded) (localLlmName ?: "Loaded") else "Not loaded",                        )                        StatChip(                            label = "Cloud",                            value = cloudProvider ?: "Not configured",                        )                    }                    Row(                        modifier = Modifier.fillMaxWidth(),                        horizontalArrangement = Arrangement.spacedBy(8.dp),                    ) {                        StatChip(                            label = "Cost",                            value = "$%.2f / $%.2f".format(monthlyCost, monthlyBudget),                        )                        StatChip(                            label = "STT",                            value = sttEngine,                        )                        StatChip(                            label = "TTS",                            value = ttsEngine,                        )                    }                    Row(                        modifier = Modifier.fillMaxWidth(),                        horizontalArrangement = Arrangement.spacedBy(8.dp),                    ) {                        StatChip(                            label = "Wake word",                            value = if (wakeWordActive) "Active" else "Off",                        )                        StatChip(                            label = "Speakers",                            value = "$speakerCount enrolled",                        )                    }                }            }        }        // Setting groups        items(groups) { group ->            GlassPanel(title = group.title) {                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {                    group.entries.forEach { entry ->                        Row(                            modifier = Modifier                                .fillMaxWidth()                                .clickable { onEntryClick(entry) }                                .padding(vertical = 8.dp),                            verticalAlignment = Alignment.CenterVertically,                        ) {                            if (entry.icon != null) {                                Icon(                                    imageVector = entry.icon,                                    contentDescription = null,                                    tint = MaterialTheme.colorScheme.primary,                                    modifier = Modifier.size(20.dp),                                )                                Spacer(modifier = Modifier.size(12.dp))                            }                            Column(modifier = Modifier.weight(1f)) {                                Text(                                    text = entry.title,                                    style = MaterialTheme.typography.bodyMedium,                                    color = MaterialTheme.colorScheme.onSurface,                                )                                Text(                                    text = entry.subtitle,                                    style = MaterialTheme.typography.labelSmall,                                    color = MaterialTheme.colorScheme.onSurfaceVariant,                                )                            }                            Icon(                                imageVector = Icons.AutoMirrored.Filled.KeyboardArrowRight,                                contentDescription = null,                                tint = MaterialTheme.colorScheme.onSurfaceVariant,                                modifier = Modifier.size(20.dp),                            )                        }                    }                }            }        }    }}